import {writeFileSync} from 'node:fs';
import {deflateSync} from 'node:zlib';
const curves=[[[90,340],[78,227],[159,205]],[[159,205],[148,146],[256,95]],[[256,95],[364,146],[353,205]],[[353,205],[434,227],[422,340]],[[119,309],[188,295],[256,352]],[[256,352],[324,295],[393,309]],[[123,331],[190,314],[256,352]],[[256,352],[323,314],[389,331]],[[115,354],[191,340],[256,369]],[[256,369],[322,340],[397,354]],[[146,279],[209,278],[256,345]],[[256,345],[303,278],[366,279]]];
