function crc(b){let c=0xffffffff;for(const v of b){c^=v;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0);}return(c^0xffffffff)>>>0;}
function chunk(type,data){const t=Buffer.from(type),n=Buffer.alloc(4),c=Buffer.alloc(4);n.writeUInt32BE(data.length);c.writeUInt32BE(crc(Buffer.concat([t,data])));return Buffer.concat([n,t,data,c]);}
function png(w,h){const pixels=Buffer.alloc(w*h*3);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const i=(y*w+x)*3;pixels[i]=11;pixels[i+1]=43;pixels[i+2]=33;}const size=Math.min(w,h)*.92,ox=(w-size)/2,oy=(h-size)/2,scale=size/512,r=Math.max(1,6.5*scale);function dot(x,y){x=x*scale+ox;y=y*scale+oy;for(let iy=Math.floor(y-r-1);iy<=y+r+1;iy++)for(let ix=Math.floor(x-r-1);ix<=x+r+1;ix++){if(ix<0||iy<0||ix>=w||iy>=h)continue;const alpha=Math.max(0,Math.min(1,r+.5-Math.hypot(ix-x,iy-y))),i=(iy*w+ix)*3;[220,193,128].forEach((v,k)=>pixels[i+k]=Math.max(pixels[i+k],Math.round([11,43,33][k]*(1-alpha)+v*alpha)));}}for(const[a,b,c]of curves)for(let j=0;j<=150;j++){const t=j/150;dot((1-t)**2*a[0]+2*(1-t)*t*b[0]+t*t*c[0],(1-t)**2*a[1]+2*(1-t)*t*b[1]+t*t*c[1]);}for(const[a,b]of lines)for(let j=0;j<=150;j++)dot(a[0]+(b[0]-a[0])*j/150,a[1]+(b[1]-a[1])*j/150);const raw=Buffer.alloc((w*3+1)*h);for(let y=0;y<h;y++)pixels.copy(raw,y*(w*3+1)+1,y*w*3,(y+1)*w*3);const hdr=Buffer.alloc(13);hdr.writeUInt32BE(w);hdr.writeUInt32BE(h,4);hdr[8]=8;hdr[9]=2;return Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]),chunk('IHDR',hdr),chunk('IDAT',deflateSync(raw)),chunk('IEND',Buffer.alloc(0))]);}
for(const size of[192,512])writeFileSync(`public/icon-${size}.png`,png(size,size));writeFileSync('public/social.png',png(1200,630));
